        result.append(node)
        for dep in dependents[node]:
            indegree[dep] -= 1
            if indegree[dep] == 0:
                # insert keeping sorted order
                lo, hi = 0, len(ready)
                while lo < hi:
                    mid = (lo + hi) // 2
                    if ready[mid] < dep:
                        lo = mid + 1
                    else:
                        hi = mid
                ready.insert(lo, dep)
    if len(result) != len(all_nodes):
