{"files": {"core.py": "import heapq


def build_order(graph):
    prerequisites = {}
    for job, dependencies in graph.items():
        prerequisites.setdefault(job, set())
        for dependency in dependencies:
            prerequisites[job].add(dependency)
            prerequisites.setdefault(dependency, set())
    dependents = {job: set() for job in prerequisites}
    indegree = {}
    for job, dependencies in prerequisites.items():
        indegree[job] = len(dependencies)
        for dependency in dependencies:
            dependents[dependency].add(job)
    ready = [job for job, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        job = heapq.heappop(ready)
        result.append(job)
        for dependent in dependents[job]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(result) != len(prerequisites):
        raise ValueError('dependency graph contains a cycle')
    return result


def job_count(graph):
    return len(set(graph).union(*(set(v) for v in graph.values())))
