{"files": {"core.py": "from copy import deepcopy

def merge_patch(target, patch):
    if not isinstance(patch, dict):
        return deepcopy(patch)
    base = target if isinstance(target, dict) else {}
    result = {}
    for k, v in base.items():
        result[k] = deepcopy(v)
    for k, pv in patch.items():
        if pv is None:
            result.pop(k, None)
        elif isinstance(pv, dict):
            if k in base:
                result[k] = merge_patch(base[k], pv)
            else:
                result[k] = merge_patch({}, pv)
        else:
            result[k] = deepcopy(pv)
    return result

def sorted_keys(document):
    return sorted(document) if isinstance(document,dict) else []
